pub fn dispatch_replace_field_formats(
    repo: &mut impl crate::kernel::Repository<CollectionRules>,
    id: &str,
    args: ReplaceFieldFormatsArgs,
    mutations: &mut Vec<crate::kernel::MutationRecord>,
    owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
    tenant_boundary_check: Result<(), crate::kernel::Refusal>,
) -> crate::kernel::DispatchResult<CollectionRules> {
    for item in &args.field_formats {
        item.check_invariants()?;
    }
    let with_references = crate::kernel::WithReferences {
        command_deref: &command_deref,
        args: &args,
        owner_deref: &owner_deref,
    };
    let seed_projections =
        crate::kernel::seeded_projections(&with_references, COLLECTION_RULES_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "ReplaceFieldFormats",
        "ConsoleSettings::CollectionRules",
        "CollectionRules",
        "agg.value",
        &with_references,
        &[],
        None,
        |record| {
            record.field_formats = args.field_formats.clone();
            Ok(())
        },
        &[],
        &collectionrules_invariants(),
        &["FieldFormatsChosen"],
        args.to_json(),
        mutations,
        seed_projections,
        tenant_boundary_check,
    )
}

